import base64
import logging
from typing import Any

from app.core.config import  settings
from app.core.external_service import ExternalService
from app.core.enums import FashnCategory
from app.schemas.fashn_category_model import FashnCategoryModel, ClothItem


class FashnAIService(ExternalService):
    """
    Service class for interacting with the FASHN AI Prediction API.
    """

    def __init__(self):
        base_url = f"{settings.AI_SITE}"
        super().__init__(base_url)  # No API key required
        self.category_model = FashnCategoryModel()  # Base model instance

    def predict(self, model_image_path: str, garment_image_path: str, category: FashnCategory):
        """
        Sends a request to the FASHN AI Prediction API.

        :param model_image_path: Path to the model image (base64 encoded).
        :param garment_image_path: Path to the garment image (base64 encoded).
        :param category: Category of the garment (must be a FashnCategory enum value).
        :return: Base64-encoded predicted image or error message.
        """

        if not isinstance(category, FashnCategory):
            logging.error(f"Invalid category '{category}'. Must be one of {FashnCategory.list()}.")
            return None

        endpoint = "/fashn/predict"
        data = {
            "model_image_base64": f"data:image/jpeg;base64,{model_image_path}",
            "garment_image_base64": f"data:image/jpeg;base64,{garment_image_path}",
            "category": category.value  # Convert Enum to string
        }

        response = self.post(endpoint=endpoint, data=data)
        # response = {
        #     "status": "completed",
        #     "result_image_base64": "data:image/jpeg;base64,",
        #     "execution_time": 0.0
        # }

        if response and response.get("status") == "completed":
            return {
                "result_image_base64": response["result_image_base64"],
                "execution_time": response["execution_time"]
            }
        else:
            logging.error(f"Prediction failed: {response}")
            return None

    def recommendation(self, image_data):
        endpoint = "/recommendations"
        payload = ClothItem(
            id=int(image_data["id"]),
            name=image_data["name"],
            color=image_data.get("colorOptions", [{}])[0].get("color", ""),
            size=image_data.get("colorOptions", [{}])[0].get("sizeOptions", [""])[0].get("size", ""),
        )

        response = self.post(endpoint=endpoint, data=payload.model_dump())
        if response and response["status"] == "success":
            return response
        else:
            logging.error(f"Recommendation failed: {response}")
            raise Exception(f"Failed to get recommendations: {response.status_code} - {response.text}")


def generate_image_logic(cloth_path, main_character, cloth) -> dict[str, Any] | str:
    ai_service = FashnAIService()

    # Valid prediction request
    category_str = cloth_path.split('/')[-2]
    category = FashnCategory(category_str)
    result = ai_service.predict(main_character, cloth, category=category)

    if result:
        print("Predicted Image (Base64):", result["result_image_base64"])
        print("Execution Time:", result["execution_time"])
        return result
    else:
        print("Prediction failed.")
        return ""
